import sys

def main():
    input = sys.stdin.read().split()
    ptr = 0
    N = int(input[ptr])
    ptr += 1
    M = int(input[ptr])
    ptr += 1

    edges = [[] for _ in range(N + 1)]
    for _ in range(M):
        s = int(input[ptr])
        ptr += 1
        t = int(input[ptr])
        ptr += 1
        edges[s].append(t)

    # Compute original expected values
    original_E = [0.0] * (N + 1)
    for v in range(N, 0, -1):
        if v == N:
            original_E[v] = 0.0
        else:
            sum_edges = 0.0
            count_edges = len(edges[v])
            for t in edges[v]:
                sum_edges += original_E[t]
            original_E[v] = 1.0 + sum_edges / count_edges

    # Collect candidate edges to block
    candidates = []
    for s in range(1, N):
        if len(edges[s]) >= 2:
            max_val = -1.0
            best_t = -1
            for t in edges[s]:
                if original_E[t] > max_val:
                    max_val = original_E[t]
                    best_t = t
            candidates.append((s, best_t))

    min_expected = original_E[1]

    for s, t in candidates:
        modified_E = [0.0] * (N + 1)
        for v in range(N, 0, -1):
            if v == N:
                modified_E[v] = 0.0
            else:
                sum_edges = 0.0
                count_edges = 0
                for t_edge in edges[v]:
                    if v == s and t_edge == t:
                        continue
                    sum_edges += modified_E[t_edge]
                    count_edges += 1
                modified_E[v] = 1.0 + sum_edges / count_edges
        current = modified_E[1]
        if current < min_expected:
            min_expected = current

    print(f"{min_expected:.10f}")

if __name__ == '__main__':
    main()
