import bisect

def main():
    import sys
    input = sys.stdin.read().split()
    N = int(input[0])
    A = list(map(int, input[1:N+1]))
    prefix = [0] * (N + 1)
    for i in range(1, N+1):
        prefix[i] = prefix[i-1] + A[i-1]
    total = prefix[N]
    candidates_i = []
    target_i = total / 4.0
    pos_i = bisect.bisect_left(prefix, target_i)
    for i in range(max(0, pos_i - 2), min(len(prefix), pos_i + 3)):
        if 1 <= i <= N - 3:
            candidates_i.append(i)
    candidates_j = []
    target_j = total / 2.0
    pos_j = bisect.bisect_left(prefix, target_j)
    for j in range(max(0, pos_j - 2), min(len(prefix), pos_j + 3)):
        if 1 <= j <= N - 2:
            candidates_j.append(j)
    candidates_k = []
    target_k = 3 * total / 4.0
    pos_k = bisect.bisect_left(prefix, target_k)
    for k in range(max(0, pos_k - 2), min(len(prefix), pos_k + 3)):
        if 1 <= k <= N - 1:
            candidates_k.append(k)
    min_diff = float('inf')
    for i in candidates_i:
        for j in candidates_j:
            if j <= i:
                continue
            for k in candidates_k:
                if k <= j:
                    continue
                P = prefix[i]
                Q = prefix[j] - prefix[i]
                R = prefix[k] - prefix[j]
                S = total - prefix[k]
                current_max = max(P, Q, R, S)
                current_min = min(P, Q, R, S)
                diff = current_max - current_min
                if diff < min_diff:
                    min_diff = diff
    print(min_diff)

if __name__ == "__main__":
    main()
