import sys

def main():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    A = list(map(int, data[1:N+1]))
    B = list(map(int, data[N+1:2*N+1]))

    B_perm = B.copy()

    if B != A:
        for i in range(N):
            if B_perm[i] != A[i]:
                continue
            # Find j > i where B_perm[j] != A[i]
            j = i + 1
            while j < N and B_perm[j] == A[i]:
                j += 1
            if j < N:
                B_perm[i], B_perm[j] = B_perm[j], B_perm[i]
            else:
                # Find j < i where B_perm[j] != A[i]
                j = i - 1
                while j >= 0 and B_perm[j] == A[i]:
                    j -= 1
                if j >= 0:
                    B_perm[i], B_perm[j] = B_perm[j], B_perm[i]
                else:
                    print("No")
                    return
        print("Yes")
        print(' '.join(map(str, B_perm)))
    else:
        # Check if all elements are the same
        all_same = True
        for i in range(1, N):
            if B[i] != B[0]:
                all_same = False
                break
        if all_same:
            print("No")
        else:
            # Find the first position where B[i] != B[i-1]
            k = 0
            while k < N - 1 and B[k] == B[k+1]:
                k += 1
            # Swap B[k] and B[k+1]
            B[k], B[k+1] = B[k+1], B[k]
            print("Yes")
            print(' '.join(map(str, B)))

if __name__ == "__main__":
    main()
